INSERT INTO `nf_wiki_pages` (`id`, `slug`, `title`, `content`, `parent_id`, `sort_order`, `published`, `user_id`, `views`, `created_at`, `updated_at`) VALUES
('14', 'guide-utilisateur', 'Guide utilisateur', '<h1>Guide utilisateur</h1>\n<p>Tout pour installer et piloter ton site <strong>NeoFrag Reborn</strong>.</p>\n', NULL, '1', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('19', 'guide-developpeur', 'Guide développeur', '<h1>Guide développeur</h1>\n<p>Étends NeoFrag Reborn : crée tes <strong>thèmes</strong>, <strong>widgets</strong> et <strong>modules</strong>, et maîtrise le framework.</p>\n', NULL, '2', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('15', 'installation', 'Installation', '<h1>Installation</h1>\n<p>NeoFrag Reborn s\'installe sur un hébergement web classique, <strong>mutualisé compris</strong>.</p>\n<h2>Prérequis</h2>\n<ul>\n<li><strong>PHP 8.2+</strong> avec les extensions <code>mysqli</code>, <code>gd</code>, <code>intl</code>, <code>mbstring</code>, <code>zip</code>, <code>curl</code>.</li>\n<li><strong>MySQL 5.7+</strong> ou <strong>MariaDB 10.5+</strong>.</li>\n<li><strong>Apache</strong> avec <code>mod_rewrite</code> (un <code>nginx.conf</code> est fourni en alternative).</li>\n<li>Une base de données vide + ses identifiants (panel de l\'hébergeur).</li>\n</ul>\n<h2>Mise en ligne</h2>\n<p>L\'assistant d\'installation se déroule en <strong>4 étapes</strong> : Prérequis → Base de données →\nAdministrateur → Terminé.</p>\n<ol>\n<li><strong>Téléverse</strong> les fichiers de NeoFrag Reborn à la racine web (FTP ou Git).</li>\n<li>Visite ton domaine : l\'<strong>assistant d\'installation</strong> se lance automatiquement et vérifie les prérequis.</li>\n<li>Renseigne la <strong>connexion base de données</strong> (une base vide) — l\'assistant importe le schéma, les migrations\n<strong>et installe tous les modules, widgets et thèmes</strong> livrés dans le paquet (modèle « tout bundlé »).</li>\n<li>Crée le <strong>compte administrateur</strong>. C\'est fini — supprime/replie l\'accès à l\'installeur si l\'hébergeur ne le fait pas.</li>\n</ol>\n<h2>Modules : tout est déjà là</h2>\n<p>NeoFrag Reborn s\'installe <strong>complet</strong> : tous les modules (actualités, forum, galerie, équipes, événements,\nwiki, boutique…), widgets et thèmes du paquet sont installés et activés d\'emblée — il n\'y a <strong>pas de choix\nde profil</strong> à l\'installation (modèle WordPress).</p>\n<p>Tu <strong>actives/désactives</strong> ensuite chaque addon depuis <strong>Admin → Thèmes &amp; Addons</strong>. Les <strong>mises à jour</strong> des\naddons (et l\'ajout d\'addons tiers) se font depuis le <a href=\"marketplace\">marketplace</a>, avec intégrité vérifiée\npar empreinte SHA-256.</p>\n<blockquote>\n<p>La page d\'accueil rend toujours quelque chose (jamais d\'écran vide) : les actualités par défaut.</p>\n</blockquote>\n<h2>Premiers réglages</h2>\n<ol>\n<li><strong>Admin → Paramètres</strong> : nom du site, description, favicon, page d\'accueil.</li>\n<li><strong>Admin → Thèmes &amp; Addons</strong> : choisis ton thème (Nebula pour une communauté) et\ninstalle les modules voulus.</li>\n<li><strong>Admin → Live Editor</strong> : compose tes pages (place tes widgets dans les zones).</li>\n<li><strong>Admin → Utilisateurs / Permissions</strong> : crée tes rôles et règle les accès.</li>\n</ol>\n<h2>Sécuriser l\'accès après l\'installation</h2>\n<p>À la fin, l\'assistant pose un <strong>verrou</strong> (<code>install/db.txt</code>) : revisiter <code>/install/</code> n\'affiche plus rien\nd\'exploitable. Par précaution, <strong>supprime (ou renomme) le dossier <code>install/</code></strong> de ton serveur — il n\'est\nplus nécessaire au fonctionnement du site. Pense aussi à activer <strong>HTTPS</strong> (Let\'s Encrypt) si l\'hébergeur\nne l\'a pas fait.</p>\n<h2>Dépannage</h2>\n<ul>\n<li><strong>« Connexion à la base impossible »</strong> : vérifie l\'hôte (souvent <code>localhost</code>, parfois une adresse dédiée\nsur les mutualisés), le port (<code>3306</code>), le nom de la base — <strong>elle doit exister et être vide</strong> — et les\nidentifiants (panel de l\'hébergeur).</li>\n<li><strong>« Extension PHP manquante »</strong> (étape Prérequis) : active l\'extension signalée (<code>mysqli</code>, <code>gd</code>, <code>intl</code>,\n<code>mbstring</code>, <code>zip</code>, <code>curl</code>) depuis le panel de l\'hébergeur, ou demande au support. En ligne de commande : <code>php -m</code>.</li>\n<li><strong>Dossier <code>config/</code> non inscriptible</strong> : l\'assistant doit y écrire <code>db.php</code> + les secrets. Donne les droits\nd\'écriture à <code>config/</code> (et à <code>cache/</code>, <code>logs/</code>, <code>upload/</code>, <code>backups/</code>).</li>\n<li><strong>Installation interrompue en cours de route</strong> : MySQL ne sait pas annuler un <code>CREATE TABLE</code> à moitié joué\n→ <strong>vide ou recrée une base vierge</strong> avant de relancer <code>/install/</code> (ne réessaie pas sur une base déjà entamée).</li>\n<li><strong>URLs en 404 / AJAX cassés sous nginx ou Plesk</strong> : le <code>.htaccess</code> n\'est lu que par Apache. Voir la note\n« nginx / Plesk » du guide de déploiement.</li>\n</ul>\n<h2>Développement local</h2>\n<p>Pour développer ou tester, une stack <strong>Docker</strong> est fournie (Apache + PHP 8.3, MariaDB,\nphpMyAdmin, Mailpit) :</p>\n<pre><code class=\"language-bash\">docker compose up -d        # http://localhost:8080\n</code></pre>\n<p>Détails (bootstrap d\'une base, migrations, tests, déploiement) :\n<code>docs/development.md</code>.</p>\n', '14', '1', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('20', 'create-a-theme', 'Créer un thème', '<h1>Créer un thème</h1>\n<p>Un <strong>thème</strong> donne au site son identité visuelle complète : la mise en page (navbar,\nzones, footer), la charte (couleurs, typographies) et les <strong>dispositions</strong> par défaut\n(quels widgets, où).</p>\n<p>Nous esquissons un thème <code>aurora</code>. Le plus simple pour démarrer est de <strong>cloner un\nthème existant</strong> (<code>themes/nebula/</code>) puis d\'adapter.</p>\n<h2>Structure des fichiers</h2>\n<pre><code>themes/aurora/\n├── aurora.php                # classe : zones, assets, dispositions\n├── views/\n│   ├── body.tpl.php          # le squelette de page (rend les zones)\n│   ├── userbar.tpl.php       # barre utilisateur (si réutilisée)\n│   └── socials.tpl.php\n├── css/\n│   └── style.css             # la charte (gabarit PHP possible)\n├── js/\n│   └── aurora.js             # interactions du thème\n└── images/\n    └── thumbnail.jpg         # vignette pour l\'admin\n</code></pre>\n<h2>1. La classe — <code>aurora.php</code></h2>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Themes\\Aurora;\n\nuse NF\\NeoFrag\\Addons\\Theme;\n\nclass Aurora extends Theme\n{\n    protected function __info()\n    {\n        return [\n            \'title\'   =&gt; \'Aurora\',\n            \'description\' =&gt; $this-&gt;lang(\'Thème communautaire dark + néon.\'),\n            \'author\'  =&gt; \'Ton Nom\',\n            \'license\' =&gt; \'Creative Commons CC BY-NC-SA 4.0\',\n            \'version\' =&gt; \'1.0.0\',\n            \'depends\' =&gt; [\'neofrag\' =&gt; \'1.0.0\'],\n            \'zones\'   =&gt; [\'Header\', \'Avant-contenu\', \'Contenu\', \'Post-contenu\', \'Footer\'],\n        ];\n    }\n\n    public function __init()\n    {\n        // Charge les assets de la page (ordre = ordre d\'inclusion).\n        $this-&gt;css(\'bootstrap.min\')\n             -&gt;css(\'icons/fontawesome.min\')\n             -&gt;css(\'style\')\n             -&gt;js(\'jquery-3.7.1.min\')-&gt;js(\'popper.min\')-&gt;js(\'bootstrap.min\')\n             -&gt;js(\'theme\')-&gt;js(\'aurora\');\n    }\n\n    public function styles_row()    { return $this-&gt;view(\'live_editor/row\'); }\n    public function styles_widget() { return $this-&gt;view(\'live_editor/widget\'); }\n\n    public function install($dispositions = [])\n    {\n        $dispositions = $this-&gt;array();\n        // … dispositions par défaut (voir §3) …\n        return parent::install($dispositions);\n    }\n}\n</code></pre>\n<ul>\n<li><code>__info().zones</code> déclare les zones dans l\'ordre. Les indices comptent : <code>zone(0)</code> =\n<em>Header</em>, <code>zone(2)</code> = <em>Contenu</em>, etc.</li>\n<li><code>__init()</code> enregistre les CSS/JS de chaque page. <code>-&gt;css(\'style\')</code> charge\n<code>css/style.css</code> du thème.</li>\n</ul>\n<h2>2. Le squelette — <code>views/body.tpl.php</code></h2>\n<p>Le <code>body.tpl.php</code> est le HTML de la page. Il <strong>rend les zones</strong> via <code>$this-&gt;output-&gt;zone(n)</code> :</p>\n<pre><code class=\"language-php\">&lt;?php $is_home = ((string) $this-&gt;url-&gt;request === \'\'); ?&gt;\n\n&lt;nav class=&quot;au-nav&quot;&gt;\n    &lt;a href=&quot;&lt;?php echo url(\'\') ?&gt;&quot;&gt;&lt;?php echo htmlspecialchars($this-&gt;config-&gt;nf_name) ?&gt;&lt;/a&gt;\n    &lt;!-- … menu, connexion … --&gt;\n&lt;/nav&gt;\n\n&lt;main&gt;\n    &lt;?php if ($zone = $this-&gt;output-&gt;zone(1)): ?&gt;&lt;div class=&quot;container&quot;&gt;&lt;?php echo $zone ?&gt;&lt;/div&gt;&lt;?php endif ?&gt;\n    &lt;?php if ($zone = $this-&gt;output-&gt;zone(2)): ?&gt;&lt;div class=&quot;container&quot;&gt;&lt;?php echo $zone ?&gt;&lt;/div&gt;&lt;?php endif ?&gt;\n    &lt;?php if ($zone = $this-&gt;output-&gt;zone(3)): ?&gt;&lt;div class=&quot;container&quot;&gt;&lt;?php echo $zone ?&gt;&lt;/div&gt;&lt;?php endif ?&gt;\n&lt;/main&gt;\n\n&lt;footer&gt;&lt;!-- … --&gt;&lt;/footer&gt;\n</code></pre>\n<blockquote>\n<p><strong>Détecter l\'accueil</strong> : sur la home, <code>$this-&gt;url-&gt;segments</code> vaut <code>[\'index\']</code> (pas\nvide). Utilise <code>((string) $this-&gt;url-&gt;request === \'\')</code>.</p>\n</blockquote>\n<p>Tu es libre : soit tu rends les zones telles quelles (navbar pilotée par les widgets de\nla zone <em>Header</em>), soit tu <strong>codes une navbar/footer sur mesure</strong> dans le <code>body.tpl</code>\n(comme les thèmes Vitrine et Nebula) pour une identité unique.</p>\n<h2>3. Les dispositions par défaut — <code>install()</code></h2>\n<p><code>install()</code> décrit, par motif de page et par zone, la grille de widgets posée à\nl\'installation du thème :</p>\n<pre><code class=\"language-php\">// Toutes les pages : module principal (8 col) + colonne latérale (4 col).\n$dispositions-&gt;set(\'*\', \'Contenu\', $this-&gt;array([\n    $this-&gt;row(\n        $this-&gt;col(\n            $this-&gt;widget($this-&gt;db-&gt;insert(\'nf_widgets\', [\'widget\' =&gt; \'module\', \'type\' =&gt; \'index\']))\n        )-&gt;size(\'col-md-8\'),\n        $this-&gt;col(\n            $this-&gt;widget($this-&gt;db-&gt;insert(\'nf_widgets\', [\'widget\' =&gt; \'user\', \'type\' =&gt; \'index\']))-&gt;style(\'panel-color\')\n        )-&gt;size(\'col-md-4\')\n    )-&gt;style(\'row-default\')\n]));\n\n// Accueil uniquement : un slider pleine largeur en avant-contenu.\n$dispositions-&gt;set(\'/\', \'Avant-contenu\', $this-&gt;array([\n    $this-&gt;row($this-&gt;col(\n        $this-&gt;widget($this-&gt;db-&gt;insert(\'nf_widgets\', [\'widget\' =&gt; \'slider\', \'type\' =&gt; \'index\']))\n    ))-&gt;style(\'row-default\')\n]));\n</code></pre>\n<ul>\n<li><code>set($page, $zone, [...rows])</code> : <code>$page</code> est un motif (<code>*</code>, <code>/</code>, <code>forum/*</code>…), le plus\nprécis l\'emporte.</li>\n<li><code>$this-&gt;widget($id)</code> reçoit l\'<strong>id</strong> d\'une ligne <code>nf_widgets</code> fraîchement insérée\n(widget + type + réglages sérialisés).</li>\n<li><code>-&gt;size(\'col-md-8\')</code> (grille Bootstrap), <code>-&gt;style(\'row-default\' | \'row-dark\')</code> et\n<code>-&gt;style(\'panel-default\' | \'panel-color\' | \'panel-header\')</code> stylent lignes et panneaux.</li>\n</ul>\n<p>Pour rendre une page <strong>pleine largeur</strong> (sans colonne latérale), ajoute une disposition\nplus précise, ex. <code>set(\'marketplace*\', \'Contenu\', [ row(col(widget(module))) ])</code>.</p>\n<h2>4. La charte — <code>css/style.css</code></h2>\n<p>Le CSS du thème peut être un <strong>gabarit PHP</strong> (servi et traité par NeoFrag ; le\n<code>?v=</code> est basé sur le mtime → toute édition invalide le cache automatiquement).</p>\n<p>NeoFrag partage des <strong>tokens génériques <code>--nf-*</code></strong> entre tous les CSS de widgets et de\nmodules. <strong>Chaque thème doit aliaser ces tokens</strong> vers sa charte dans <code>:root</code>, sinon les\ncomposants tombent sur des valeurs de repli :</p>\n<pre><code class=\"language-css\">:root {\n    --nf-bg:      #070a10;\n    --nf-surface: rgba(255, 255, 255, .035);\n    --nf-border:  rgba(255, 255, 255, .09);\n    --nf-text:    #e7eef6;\n    --nf-muted:   #8593a6;\n    --nf-accent:  #2dd4bf;   /* la couleur d\'accent de TA charte */\n}\n</code></pre>\n<p>Ainsi un widget tiers (qui écrit <code>color: var(--nf-accent)</code>) prend automatiquement la\ncouleur de ton thème.</p>\n<h2>5. Installer &amp; activer le thème</h2>\n<ol>\n<li>Dépose <code>themes/aurora/</code>.</li>\n<li><strong>Admin → Thèmes &amp; Addons → Scanner le disque</strong> → coche <code>aurora</code> → installe (les\ndispositions par défaut sont créées).</li>\n<li>Active-le : bouton <strong>Activer</strong> sur sa fiche (définit le thème par défaut), ou via le\nsélecteur de thème en pied de page (cookie <code>nf_theme</code>).</li>\n</ol>\n<p>Le bouton <strong>Réinstaller par défaut</strong> (fiche du thème) ré-exécute <code>install()</code> : utile\naprès avoir modifié tes dispositions par défaut.</p>\n<h2>Bonnes pratiques</h2>\n<ul>\n<li><strong>Dark-only ?</strong> force l\'attribut via <code>js/theme.js</code>\n(<code>document.documentElement.setAttribute(\'data-theme\', \'dark\')</code>).</li>\n<li><strong>Polices</strong> : préfère charger les Google Fonts via <code>&lt;link&gt;</code> plutôt qu\'un <code>@import</code> en\ntête de CSS (un <code>@import</code> bloque le rendu et peut provoquer un flash au chargement).</li>\n<li><strong>Crédite</strong> le projet original (NeoFrag, Michaël BILCOT &amp; Jérémy VALENTIN, LGPLv3) si\ntu pars d\'un thème existant.</li>\n</ul>\n', '19', '1', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('16', 'concepts', 'Concepts', '<h1>Concepts</h1>\n<p>Comprendre ces cinq notions suffit à maîtriser NeoFrag Reborn.</p>\n<h2>Modules</h2>\n<p>Un <strong>module</strong> est une fonctionnalité complète : le forum, les actualités, la galerie,\nles membres, la boutique… Chaque module apporte ses <strong>pages publiques</strong> (ce que voient\nles visiteurs), son <strong>interface d\'administration</strong>, ses <strong>données</strong> (tables) et ses\n<strong>permissions</strong>.</p>\n<p>Tu actives ou désactives les modules depuis <strong>Admin → Thèmes &amp; Addons</strong>. Un module\ndésactivé disparaît du site mais conserve ses données.</p>\n<p>L\'installation fournit <strong>tous les modules</strong> du paquet (modèle « tout bundlé », comme\nWordPress) : ils sont installés et activés d\'emblée, <strong>sans choix de profil</strong>. Tu règles\nensuite leur visibilité via <strong>Admin → Thèmes &amp; Addons</strong> (activer/désactiver) et\n<strong>Admin → Permissions</strong> (RBAC). D\'autres addons, non livrés dans le paquet, s\'ajoutent\ndepuis le <strong>marketplace</strong>.</p>\n<h2>Widgets</h2>\n<p>Un <strong>widget</strong> est un petit bloc réutilisable : le menu de navigation, l\'espace membre,\nles derniers commentaires, un compte à rebours, un lecteur Twitch… Un même widget peut\nêtre placé plusieurs fois, à des endroits différents, avec des réglages différents.</p>\n<p>Les widgets se posent dans les <strong>zones</strong> du thème via le <strong>Live Editor</strong> (éditeur\nvisuel) ou via les <strong>dispositions</strong> définies par le thème.</p>\n<h2>Thèmes</h2>\n<p>Un <strong>thème</strong> donne l\'identité visuelle du site : couleurs, typographies, mise en page,\nnavbar, footer. Le thème déclare des <strong>zones</strong> et organise le contenu via des\n<strong>dispositions</strong>.</p>\n<p>NeoFrag Reborn fournit deux thèmes cœur :</p>\n<ul>\n<li><strong>Vitrine</strong> — le thème officiel (landing moderne, dédié au site de présentation).</li>\n<li><strong>Nebula</strong> — un thème communautaire généraliste (dark navy + teal), pensé pour ta\nteam, ta guilde ou ta communauté.</li>\n</ul>\n<p>D\'autres thèmes (Granite, Forge, Blockcraft…) sont disponibles au téléchargement sur le\nmarketplace. Le thème actif se choisit dans <strong>Admin → Thèmes &amp; Addons</strong>, et les\nvisiteurs peuvent en changer via le sélecteur en bas de page (si plusieurs sont\ninstallés).</p>\n<h2>Zones &amp; dispositions</h2>\n<p>Un thème découpe la page en <strong>zones</strong> : généralement <em>Header</em>, <em>Avant-contenu</em>,\n<em>Contenu</em>, <em>Post-contenu</em>, <em>Footer</em>.</p>\n<p>Une <strong>disposition</strong> décrit, pour une page donnée (ou un motif de pages), quels widgets\noccupent quelle zone et dans quelle grille. Les motifs vont du plus général au plus\nprécis :</p>\n<table>\n<thead>\n<tr>\n<th>Motif</th>\n<th>S\'applique à</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>*</code></td>\n<td>toutes les pages</td>\n</tr>\n<tr>\n<td><code>/</code></td>\n<td>la page d\'accueil uniquement</td>\n</tr>\n<tr>\n<td><code>forum/*</code></td>\n<td>toutes les pages du forum</td>\n</tr>\n</tbody>\n</table>\n<p>Le motif le plus précis l\'emporte. Exemple : une disposition <code>*</code> met le contenu sur\n8 colonnes + une colonne latérale de widgets, tandis qu\'une disposition <code>marketplace*</code>\npeut passer la même page en pleine largeur.</p>\n<p>Tu modifies les dispositions à la souris avec le <strong>Live Editor</strong>.</p>\n<h2>Addons &amp; marketplace</h2>\n<p><strong>Addon</strong> est le terme générique pour tout ce qui s\'installe : modules, widgets,\nthèmes et connecteurs d\'authentification (Discord, GitHub, Google…).</p>\n<p>Le <strong><a href=\"marketplace\">marketplace</a></strong> est le catalogue public où tu trouves et\ntélécharges des addons (<code>.zip</code>). L\'installation se fait ensuite en deux clics depuis\n<strong>Admin → Thèmes &amp; Addons → Ajouter</strong>.</p>\n<p>Techniquement, un addon n\'est qu\'un <strong>dossier de fichiers PHP</strong> : tu peux le versionner,\nle partager, et le réinstaller sur n\'importe quel site NeoFrag Reborn. C\'est ce qui rend\nle CMS infiniment extensible — voir les guides développeur.</p>\n<h2>En pratique : monter une communauté</h2>\n<p>Pour une team gaming, concrètement : dans <em>Thèmes &amp; Addons</em> tu actives les modules <strong>forum</strong>, <strong>équipes</strong>\net <strong>événements</strong> (déjà installés) et tu passes sur le thème <strong>Nebula</strong> ; puis, avec le <strong>Live Editor</strong>, tu\nplaces le widget <strong>navigation</strong> dans le <em>Header</em> et un widget de contenu (derniers sujets, prochains\nmatchs…) dans la colonne latérale de l\'accueil. Tout se règle dans l\'admin, <strong>sans une ligne de code</strong>.</p>\n<h2>Surcharge sans forker</h2>\n<p>Tout fichier livré (vue, classe, asset) peut être <strong>surchargé</strong> sans modifier le code\nd\'origine. Le framework résout dans cet ordre (le premier trouvé gagne) :</p>\n<ol>\n<li><code>overrides/{type}/{fichier}</code> — surcharge globale</li>\n<li><code>themes/{thème actif}/overrides/{type}/{fichier}</code> — surcharge par thème</li>\n<li>l\'original livré</li>\n</ol>\n<p>Tu adaptes ainsi un module ou un widget à ton site (ou à un thème précis) sans jamais\ntoucher au cœur — et sans casser les mises à jour.</p>\n', '14', '2', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('21', 'create-a-widget', 'Créer un widget', '<h1>Créer un widget</h1>\n<p>Un <strong>widget</strong> est un bloc réutilisable plaçable dans n\'importe quelle zone d\'un thème.\nC\'est l\'addon le plus simple à écrire : une classe, un contrôleur, une vue.</p>\n<p>Nous allons créer un widget <code>hello</code> qui affiche un message de bienvenue paramétrable.</p>\n<h2>Structure des fichiers</h2>\n<pre><code>widgets/hello/\n├── hello.php                 # la classe du widget (métadonnées)\n├── controllers/\n│   ├── index.php             # le contrôleur (prépare et rend la vue)\n│   └── admin.php             # formulaire de réglages (optionnel)\n├── views/\n│   ├── index.tpl.php         # le gabarit HTML\n│   └── admin.tpl.php         # gabarit des réglages (optionnel)\n└── css/\n    └── hello.css             # styles (optionnel)\n</code></pre>\n<h2>1. La classe — <code>hello.php</code></h2>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Widgets\\Hello;\n\nuse NF\\NeoFrag\\Addons\\Widget;\n\nclass Hello extends Widget\n{\n    protected function __info()\n    {\n        return [\n            \'title\'       =&gt; $this-&gt;lang(\'Bienvenue\'),\n            \'description\' =&gt; \'Affiche un message de bienvenue personnalisable.\',\n            \'icon\'        =&gt; \'fas fa-hand-spock\',\n            \'author\'      =&gt; \'Ton Nom\',\n            \'license\'     =&gt; \'LGPLv3\',\n            \'version\'     =&gt; \'1.0.0\',\n            \'depends\'     =&gt; [\'neofrag\' =&gt; \'1.0.0\'],\n        ];\n    }\n}\n</code></pre>\n<ul>\n<li><code>namespace</code> <strong>doit</strong> suivre le dossier : <code>NF\\Widgets\\&lt;Name&gt;</code>.</li>\n<li><code>__info()</code> renvoie les métadonnées. <code>version</code> et <code>depends.neofrag</code> sont obligatoires\n(l\'installeur les vérifie).</li>\n<li>Les <strong>réglages</strong> d\'un widget configurable ne se déclarent <strong>pas</strong> dans cette classe, mais dans un\ncontrôleur dédié <code>controllers/admin.php</code> (voir l\'étape « Réglages » plus bas). Sans lui, le widget\nn\'a pas de réglages.</li>\n</ul>\n<h2>2. Le contrôleur — <code>controllers/index.php</code></h2>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Widgets\\Hello\\Controllers;\n\nuse NF\\NeoFrag\\Loadables\\Controllers\\Widget as Controller_Widget;\n\nclass Index extends Controller_Widget\n{\n    public function index($settings = [])\n    {\n        return $this-&gt;css(\'hello\')-&gt;view(\'index\', [\n            \'message\' =&gt; $settings[\'message\'] ?? $this-&gt;lang(\'Bienvenue !\'),\n        ]);\n    }\n}\n</code></pre>\n<p>Le contrôleur reçoit les <code>$settings</code> saisis par l\'admin, prépare les données, charge\nson CSS et rend sa vue. Le chaînage <code>-&gt;css(\'hello\')-&gt;view(\'index\', $data)</code> est le\npattern standard.</p>\n<h2>3. La vue — <code>views/index.tpl.php</code></h2>\n<pre><code class=\"language-php\">&lt;div class=&quot;hello-widget&quot;&gt;\n    &lt;i class=&quot;fas fa-hand-spock&quot;&gt;&lt;/i&gt;\n    &lt;span&gt;&lt;?php echo htmlspecialchars($message) ?&gt;&lt;/span&gt;\n&lt;/div&gt;\n</code></pre>\n<p>Les variables passées à <code>view()</code> sont disponibles directement (<code>$message</code>). <strong>Échappe\ntoujours</strong> les données affichées (<code>htmlspecialchars</code>).</p>\n<h2>4. Le CSS — <code>css/hello.css</code> (optionnel)</h2>\n<pre><code class=\"language-css\">.hello-widget { display: flex; align-items: center; gap: 10px; padding: 14px 16px; }\n.hello-widget i { color: var(--nf-accent, #2dd4bf); }\n</code></pre>\n<blockquote>\n<p>Pour rester cohérent avec tous les thèmes, utilise les tokens partagés <code>--nf-*</code>\n(avec une valeur de repli). Chaque thème les redéfinit selon sa charte. Voir\n<a href=\"create-a-theme\">Créer un thème</a>.</p>\n</blockquote>\n<h2>5. Les réglages — <code>controllers/admin.php</code> (optionnel)</h2>\n<p>Pour qu\'un widget soit <strong>configurable</strong>, ajoute un contrôleur <code>controllers/admin.php</code> : il rend le\nformulaire de réglages, et ses champs alimentent les <code>$settings</code> que reçoit le contrôleur <code>index</code>. La\nclasse étend <code>Controller</code> (pas <code>Widget</code>) et expose <code>index($settings = [])</code> :</p>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Widgets\\Hello\\Controllers;\n\nuse NF\\NeoFrag\\Loadables\\Controller;\n\nclass Admin extends Controller\n{\n    public function index($settings = [])\n    {\n        return $this-&gt;view(\'admin\', [\n            \'message\' =&gt; $settings[\'message\'] ?? $this-&gt;lang(\'Bienvenue sur le site !\'),\n        ]);\n    }\n}\n</code></pre>\n<p>La vue <code>views/admin.tpl.php</code> rend les champs ; chaque champ doit être nommé <code>settings[&lt;clé&gt;]</code> pour que\nsa valeur revienne dans <code>$settings[\'&lt;clé&gt;\']</code> :</p>\n<pre><code class=\"language-php\">&lt;div class=&quot;form-group row&quot;&gt;\n    &lt;label for=&quot;settings-message&quot; class=&quot;col-4 col-form-label&quot;&gt;&lt;?php echo $this-&gt;lang(\'Message\') ?&gt;&lt;/label&gt;\n    &lt;div class=&quot;col-7&quot;&gt;\n        &lt;input class=&quot;form-control&quot; type=&quot;text&quot; name=&quot;settings[message]&quot; id=&quot;settings-message&quot;\n               value=&quot;&lt;?php echo htmlspecialchars($message) ?&gt;&quot;&gt;\n    &lt;/div&gt;\n&lt;/div&gt;\n</code></pre>\n<h2>6. Valider les réglages — <code>controllers/checker.php</code> (optionnel)</h2>\n<p>Pour un widget à <strong>plusieurs réglages</strong>, plutôt que de semer des <code>?? défaut</code> dans le contrôleur, ajoute\nun <strong>checker</strong> : sa méthode <code>index($settings)</code> reçoit les réglages <strong>bruts</strong> et <strong>retourne</strong> un tableau\n<strong>validé et complété de ses défauts</strong>. Ce tableau devient les <code>$settings</code> du contrôleur <code>index</code> — qui peut\nalors leur faire confiance (valeurs bornées, jamais d\'entrée brute affichée).</p>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Widgets\\Hello\\Controllers;\n\nuse NF\\NeoFrag\\Loadables\\Controller;\n\nclass Checker extends Controller\n{\n    public function index($settings = [])\n    {\n        return [\n            \'message\' =&gt; isset($settings[\'message\']) &amp;&amp; $settings[\'message\'] !== \'\'\n                       ? $settings[\'message\'] : $this-&gt;lang(\'Bienvenue !\'),\n            \'align\'   =&gt; in_array($settings[\'align\'] ?? \'\', [\'left\', \'center\', \'right\'], TRUE)\n                       ? $settings[\'align\'] : \'left\',\n        ];\n    }\n}\n</code></pre>\n<p>C\'est le pattern du widget <code>about</code> (<code>widgets/about/controllers/checker.php</code>) : chaque réglage est borné à\ndes valeurs connues, avec un défaut sûr.</p>\n<h2>7. Installer &amp; placer le widget</h2>\n<ol>\n<li>Dépose le dossier <code>widgets/hello/</code> sur ton site.</li>\n<li>Va dans <strong>Admin → Thèmes &amp; Addons → Scanner le disque</strong>, coche <code>hello</code>, installe.</li>\n<li>Place-le dans une zone via le <strong>Live Editor</strong>, configure son message, enregistre.</li>\n</ol>\n<h2>Aller plus loin</h2>\n<ul>\n<li>Un widget peut exposer <strong>plusieurs types</strong> (méthodes du contrôleur autres que\n<code>index</code>) : <code>news</code> propose <code>index</code>, <code>categories</code>… Le type se choisit à la pose.</li>\n<li>Pour un widget distribuable, ajoute un <code>README</code> et une capture, puis zippe le dossier\n(<code>widgets/hello/</code> à la racine de l\'archive) : il s\'installera via <strong>Ajouter</strong> (ZIP).</li>\n<li>Besoin de données ? Lis-les avec l\'ORM (<code>NeoFrag()-&gt;db-&gt;select(...)</code>). Voir\n<a href=\"framework\">Le framework</a>.</li>\n</ul>\n', '19', '2', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('17', 'admin', 'Administration', '<h1>Le panel d\'administration</h1>\n<p>L\'administration se trouve sous <strong>/admin</strong>. Elle adopte la charte NeoFrag Reborn\n(dark navy + teal, clair/sombre au choix) et s\'organise autour d\'une <strong>barre latérale</strong>.</p>\n<h2>Repères</h2>\n<ul>\n<li><strong>Barre latérale</strong> : les modules sont regroupés par catégories claires — <em>Contenu</em>,\n<em>Communauté</em>, <em>Connaissance</em> (wiki, FAQ), <em>Média</em>, <em>Gaming</em>, <em>Monétisation</em> — plus <em>Système</em> et\n<em>Monitoring</em>. Les sections se déplient en accordéon ; une catégorie vide est masquée.</li>\n<li><strong>Épingles</strong> : survole un module dans la sidebar et clique l\'épingle pour l\'ajouter à\n<em>Épinglé</em> (raccourcis en haut, mémorisés dans ton navigateur).</li>\n<li><strong>Recherche rapide</strong> : <code>Ctrl/Cmd + K</code> ouvre la palette de commandes pour sauter à\nn\'importe quel module ou action.</li>\n<li><strong>En-tête</strong> : fil d\'ariane + actions contextuelles (Permissions, Configuration, Aide),\n« Voir le site » et bascule clair/sombre.</li>\n</ul>\n<h2>Tâches courantes</h2>\n<table>\n<thead>\n<tr>\n<th>Je veux…</th>\n<th>J\'y vais</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Publier une actu / un article / une page</td>\n<td><em>Contenu</em> → le module concerné</td>\n</tr>\n<tr>\n<td>Gérer le forum, les commentaires, la modération</td>\n<td><em>Communauté</em></td>\n</tr>\n<tr>\n<td>Gérer membres, groupes, sessions</td>\n<td><em>Système → Utilisateurs</em></td>\n</tr>\n<tr>\n<td>Régler qui peut faire quoi</td>\n<td><em>Système → Permissions (matrice)</em> — grille rôle × action (vert = autorisé, gris = défaut, rouge = jamais)</td>\n</tr>\n<tr>\n<td>Changer le thème / installer un addon</td>\n<td><em>Système → Thèmes &amp; Addons</em></td>\n</tr>\n<tr>\n<td>Réglages du site (nom, accueil, inscriptions, sécurité, copyright)</td>\n<td><em>Système → Paramètres</em></td>\n</tr>\n<tr>\n<td>Composer les pages à la souris</td>\n<td><em>Système → Live Editor</em></td>\n</tr>\n<tr>\n<td>Sauvegardes, mises à jour, état du site, journal d\'audit</td>\n<td><em>Monitoring</em></td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Monitoring</strong> réunit la <strong>santé du site</strong> (vérifications d\'intégrité des fichiers, espace disque, infos\nserveur, état des tâches cron), les <strong>sauvegardes</strong> (créer / télécharger / restaurer) et le <strong>journal\nd\'audit</strong> des actions sensibles (réglages, addons, comptes).</p>\n</blockquote>\n<h2>Permissions</h2>\n<p>NeoFrag Reborn fonctionne par <strong>rôles</strong>. La <strong>matrice de permissions</strong> (par module)\nrègle, pour chaque rôle, l\'accès et les actions. Tu assignes les rôles aux membres et\naux groupes depuis <em>Système</em>.</p>\n<p><strong>Exemple — créer un rôle « Modérateur »</strong> :</p>\n<ol>\n<li>Dans <em>Système → Permissions</em>, <strong>crée un rôle</strong> « Modérateur ».</li>\n<li>Sur sa colonne de la <strong>matrice</strong>, coche les actions voulues (modérer le forum, gérer les\ncommentaires…) → <strong>vert = autorisé</strong>.</li>\n<li>Dans <em>Système → Utilisateurs</em>, édite un membre et <strong>assigne-lui ce rôle</strong> : il hérite aussitôt de ces accès.</li>\n</ol>\n<h2>Réglages essentiels</h2>\n<p>Dans <strong>Paramètres</strong> : titre et description du site, favicon, email de contact, page\nd\'accueil, gestion des inscriptions, sécurité anti-bots (captcha), maintenance,\ncopyright, réseaux sociaux. Ces réglages alimentent les thèmes et les widgets.</p>\n', '14', '3', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('22', 'create-a-module', 'Créer un module', '<h1>Créer un module</h1>\n<p>Un <strong>module</strong> est une fonctionnalité complète : ses pages publiques, ses routes, son\nadministration, ses données et ses permissions. C\'est l\'addon le plus riche.</p>\n<p>Nous allons créer un module <code>notes</code> qui affiche une liste de notes publiques.</p>\n<h2>Structure des fichiers</h2>\n<pre><code>modules/notes/\n├── notes.php                 # classe : métadonnées, routes, permissions\n├── controllers/\n│   ├── checker.php           # charge les données et valide la route\n│   ├── index.php             # rend les pages publiques\n│   └── admin.php             # interface d\'administration (optionnel)\n├── install/\n│   ├── install.sql           # tables du module (joué à l\'installation)\n│   └── uninstall.sql         # suppression des tables\n├── views/\n│   └── index.tpl.php\n├── css/\n│   └── notes.css             # optionnel\n└── langs/\n    └── fr.php                # traductions (optionnel)\n</code></pre>\n<h2>1. La classe — <code>notes.php</code></h2>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Modules\\Notes;\n\nuse NF\\NeoFrag\\Addons\\Module;\n\nclass Notes extends Module\n{\n    protected function __info()\n    {\n        return [\n            \'title\'       =&gt; $this-&gt;lang(\'Notes\'),\n            \'description\' =&gt; \'Petites notes publiques.\',\n            \'icon\'        =&gt; \'fas fa-note-sticky\',\n            \'author\'      =&gt; \'Ton Nom\',\n            \'license\'     =&gt; \'LGPLv3\',\n            \'admin\'       =&gt; TRUE,          // expose une page d\'administration\n            \'version\'     =&gt; \'1.0.0\',\n            \'depends\'     =&gt; [\'neofrag\' =&gt; \'1.0.0\'],\n            \'routes\'      =&gt; [\n                \'\'                 =&gt; \'index\',     // /notes\n                \'{id}/{url_title}\' =&gt; \'_show\',      // /notes/42/ma-note\n            ],\n        ];\n    }\n}\n</code></pre>\n<h3>Les routes</h3>\n<p>Une route mappe un <strong>motif d\'URL</strong> vers une <strong>méthode de contrôleur</strong>. Le motif est\nrelatif au nom du module (<code>\'\'</code> = la page d\'accueil du module, ici <code>/notes</code>).</p>\n<blockquote>\n<p><strong>Important</strong> — les placeholders sont un ensemble <strong>fixe</strong> : <code>{id}</code> (entier),\n<code>{key_id}</code>, <code>{url_title}</code> (slug), <code>{url_title*}</code>, <code>{page}</code> et <code>{pages}</code> (pagination). Un\nplaceholder inconnu produit un 404 silencieux. Pour une fiche, le motif idiomatique est\n<code>{id}/{url_title}</code> (l\'<code>id</code> valide la fiche, le slug est cosmétique).</p>\n</blockquote>\n<h2>2. Le checker — <code>controllers/checker.php</code></h2>\n<p>Le <strong>checker</strong> s\'exécute avant le contrôleur : il charge les données et <strong>valide</strong> la\nroute (renvoyer <code>FALSE</code> ou rien déclenche un 404). Ce qu\'il <strong>retourne devient les\narguments</strong> de la méthode de même nom du contrôleur.</p>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Modules\\Notes\\Controllers;\n\nuse NF\\NeoFrag\\Loadables\\Controllers\\Module_Checker;\n\nclass Checker extends Module_Checker\n{\n    public function index()\n    {\n        $notes = NeoFrag()-&gt;db-&gt;select(\'id\', \'title\', \'body\')\n                              -&gt;from(\'nf_notes\')\n                              -&gt;order_by(\'id DESC\')\n                              -&gt;get();\n\n        return [$notes];   // → index($notes)\n    }\n}\n</code></pre>\n<h2>3. Le contrôleur public — <code>controllers/index.php</code></h2>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Modules\\Notes\\Controllers;\n\nuse NF\\NeoFrag\\Loadables\\Controllers\\Module as Controller_Module;\n\nclass Index extends Controller_Module\n{\n    public function index($notes)\n    {\n        $this-&gt;title($this-&gt;lang(\'Notes\'))\n             -&gt;icon(\'fas fa-note-sticky\')\n             -&gt;breadcrumb();\n\n        return $this-&gt;css(\'notes\')-&gt;view(\'index\', [\'notes\' =&gt; $notes]);\n    }\n}\n</code></pre>\n<p><code>title()</code>, <code>icon()</code>, <code>breadcrumb()</code> renseignent l\'en-tête de page. Le contrôleur rend\nensuite sa vue (ou un panneau via <code>$this-&gt;panel()-&gt;title()-&gt;body($html)</code> pour du HTML\nconstruit en PHP).</p>\n<h2>4. La vue — <code>views/index.tpl.php</code></h2>\n<pre><code class=\"language-php\">&lt;div class=&quot;notes&quot;&gt;\n    &lt;?php if (empty($notes)): ?&gt;\n        &lt;div class=&quot;alert alert-info&quot;&gt;&lt;?php echo $this-&gt;lang(\'Aucune note.\') ?&gt;&lt;/div&gt;\n    &lt;?php else: foreach ($notes as $n): ?&gt;\n        &lt;article class=&quot;note&quot;&gt;\n            &lt;h3&gt;&lt;?php echo htmlspecialchars($n[\'title\']) ?&gt;&lt;/h3&gt;\n            &lt;p&gt;&lt;?php echo htmlspecialchars($n[\'body\']) ?&gt;&lt;/p&gt;\n        &lt;/article&gt;\n    &lt;?php endforeach; endif ?&gt;\n&lt;/div&gt;\n</code></pre>\n<h2>5. Les données</h2>\n<p>Un module <strong>livre ses tables</strong> dans <code>modules/notes/install/install.sql</code> (et leur suppression dans\n<code>install/uninstall.sql</code>). Ce SQL est joué <strong>automatiquement à l\'installation du module</strong> (scan admin,\nreset, ou install d\'un ZIP marketplace), idempotent grâce à <code>CREATE TABLE IF NOT EXISTS</code> :</p>\n<pre><code class=\"language-sql\">-- modules/notes/install/install.sql\nCREATE TABLE IF NOT EXISTS nf_notes (\n    id    INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,\n    title VARCHAR(255) NOT NULL,\n    body  TEXT NOT NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n</code></pre>\n<blockquote>\n<p><strong>Pas de tables propres ? Pas de <code>install.sql</code>.</strong> Un module qui réutilise des tables du cœur (par\nexemple <code>nf_file</code> via <code>model2(\'file\')</code>, comme les modules <code>files</code> ou <code>menu</code>) n\'a <strong>ni <code>install.sql</code> ni\n<code>uninstall.sql</code></strong> — il s\'installe sans rien toucher au schéma. Ne livre du SQL que pour <strong>tes propres</strong> tables.</p>\n</blockquote>\n<p>Le dossier <code>migrations/</code> <strong>à la racine</strong> du projet est réservé aux <strong>évolutions transverses du cœur</strong>\n(multi-modules). <code>php tools/extract-module-sql.php</code> (re)génère les <code>install.sql</code> par module à partir de\nla base de dev. (Voir <a href=\"framework\">Le framework</a>.)</p>\n<h3>Faire évoluer le schéma entre deux versions — migrations par-addon</h3>\n<p><code>install.sql</code> est <strong>idempotent</strong> : il crée les tables manquantes mais ne <strong>modifie pas</strong> une table déjà\nprésente chez les utilisateurs. Pour un changement de schéma (ajouter/renommer/supprimer une colonne,\nmigrer des données) entre deux versions de ton module, ajoute un fichier de <strong>migration</strong> :</p>\n<pre><code>modules/notes/install/migrations/2026_07_01_add_pinned.up.sql\n</code></pre>\n<pre><code class=\"language-sql\">ALTER TABLE nf_notes ADD COLUMN pinned TINYINT(1) NOT NULL DEFAULT 0;\n</code></pre>\n<ul>\n<li>Nom = <strong>préfixe daté</strong> (<code>YYYY_MM_DD_description</code>) → exécution dans l\'ordre.</li>\n<li>Suivi dans <code>nf_addon_migrations</code> : chaque migration ne s\'exécute <strong>qu\'une seule fois</strong>.</li>\n<li>À l\'<strong>install neuve</strong> (<code>install.sql</code> porte déjà le schéma à jour), les migrations sont <strong>baselinées</strong>\n(marquées sans être jouées). À la <strong>mise à jour</strong> (admin → marketplace → « Mises à jour »), seules les\nmigrations <strong>nouvelles</strong> sont <strong>exécutées</strong> (<code>Addon::update()</code>).</li>\n<li>Règle d\'or : <strong>n\'écris une migration que pour une vraie évolution d\'un schéma déjà livré</strong>. Une nouvelle\ntable va dans <code>install.sql</code> (idempotent), jamais dans une migration.</li>\n</ul>\n<h2>6. Les permissions (optionnel)</h2>\n<pre><code class=\"language-php\">public function permissions()\n{\n    return [\n        \'default\' =&gt; [\'access\' =&gt; [[\n            \'title\'  =&gt; \'Notes\',\n            \'icon\'   =&gt; \'fas fa-note-sticky\',\n            \'access\' =&gt; [\n                \'manage\' =&gt; [\'title\' =&gt; $this-&gt;lang(\'Gérer les notes\'), \'admin\' =&gt; TRUE],\n            ],\n        ]]],\n    ];\n}\n</code></pre>\n<p>Les permissions deviennent éditables dans <strong>Admin → Permissions (matrice)</strong> : tu y\nrègles, par rôle, qui peut voir le module et qui peut le gérer.</p>\n<h2>7. L\'administration (optionnel)</h2>\n<p>Si <code>\'admin\' =&gt; TRUE</code>, ajoute <code>controllers/admin.php</code> (classe <code>Admin extends Controller_Module</code>). Sa méthode <code>index()</code> est servie sous <code>/admin/notes</code> et hérite\nautomatiquement de la nouvelle interface (sidebar, breadcrumb, actions).</p>\n<pre><code class=\"language-php\">&lt;?php\nnamespace NF\\Modules\\Notes\\Controllers;\n\nuse NF\\NeoFrag\\Loadables\\Controllers\\Module as Controller_Module;\n\nclass Admin extends Controller_Module\n{\n    public function index()\n    {\n        $this-&gt;title($this-&gt;lang(\'Notes\'))-&gt;icon(\'fas fa-note-sticky\');\n\n        // En admin, on utilise l\'API form() + add_rules() (celle des modules du cœur).\n        $this-&gt;form()\n             -&gt;add_rules([\n                 \'title\' =&gt; [\'label\' =&gt; $this-&gt;lang(\'Titre\'),   \'type\' =&gt; \'text\',   \'rules\' =&gt; \'required\'],\n                 \'body\'  =&gt; [\'label\' =&gt; $this-&gt;lang(\'Contenu\'), \'type\' =&gt; \'editor\'],\n             ])\n             -&gt;add_submit($this-&gt;lang(\'Ajouter\'));\n\n        if ($this-&gt;form()-&gt;is_valid($post))\n        {\n            NeoFrag()-&gt;db-&gt;insert(\'nf_notes\', [\'title\' =&gt; $post[\'title\'], \'body\' =&gt; $post[\'body\']]);\n            notify($this-&gt;lang(\'Note ajoutée.\'));\n            redirect(\'admin/notes\');\n        }\n\n        return $this-&gt;admin_card(\'fas fa-note-sticky\', $this-&gt;lang(\'Notes\'), $this-&gt;form()-&gt;display());\n    }\n}\n</code></pre>\n<p>Les helpers <code>admin_card()</code>, <code>admin_back()</code> et <code>admin_empty()</code> habillent le contenu (carte, bouton retour,\nétat vide). C\'est <strong><code>form()</code></strong> (avec <code>add_rules()</code> / <code>is_valid()</code>) qui est l\'API de formulaire d\'admin\nemployée par les modules ; <code>form2()</code> (cf. <a href=\"framework\">Le framework</a>) est réservé aux formulaires riches\nou de confirmation.</p>\n<h2>Installer le module</h2>\n<ol>\n<li>Dépose <code>modules/notes/</code>.</li>\n<li><strong>Admin → Thèmes &amp; Addons → Scanner le disque</strong> → coche <code>notes</code> → installe (l\'install\njoue <code>install/install.sql</code> : les tables sont créées à ce moment).\n(Les modules sont décochés par défaut : leur install est plus intrusive — tables,\npermissions, navigation.)</li>\n</ol>\n<p>Pour distribuer le module, zippe le dossier (<code>modules/notes/</code> à la racine de l\'archive).</p>\n', '19', '3', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('18', 'marketplace', 'Marketplace', '<h1>Le marketplace</h1>\n<p>Le <strong>marketplace</strong> sert à <strong>mettre à jour</strong> tes addons et à <strong>ajouter des addons tiers</strong> non livrés\ndans le paquet. NeoFrag Reborn s\'installe déjà <strong>complet</strong> (tous les modules/widgets/thèmes du paquet,\nmodèle « tout bundlé ») ; le marketplace intervient <em>après</em> l\'installation, depuis l\'administration.</p>\n<p>Le catalogue et les archives sont servis depuis <strong>neofrag-reborn.xyz</strong>. Chaque archive est vérifiée\npar <strong>empreinte SHA-256</strong> au téléchargement (intégrité), via HTTPS.</p>\n<h2>Installer un addon tiers</h2>\n<p>Deux chemins :</p>\n<h3>1. En un clic depuis l\'administration</h3>\n<p><strong>Admin → Thèmes &amp; Addons → Marketplace</strong>. La fenêtre liste les addons disponibles non installés ;\ncoche-les et clique <strong>Installer</strong> — NeoFrag télécharge, vérifie l\'empreinte SHA-256, extrait et\nenregistre l\'addon (ainsi que son widget apparié, le cas échéant).</p>\n<h3>2. Manuellement (archive ZIP)</h3>\n<p>La page <strong>Marketplace</strong> (front) présente chaque addon en fiche avec un bouton <strong>Télécharger</strong>. Tu peux\naussi : télécharger le <code>.zip</code>, puis <strong>Admin → Thèmes &amp; Addons → Ajouter</strong> et envoyer l\'archive (l\'upload\nest validé : les archives au contenu non sûr sont refusées).</p>\n<h2>Mettre à jour ou retirer</h2>\n<ul>\n<li><strong>Mettre à jour</strong> : <strong>Admin → Thèmes &amp; Addons → Mises à jour</strong> compare la version installée de chaque\naddon à celle du catalogue et liste celles à mettre à jour ; applique-les en un clic (téléchargement +\nSHA-256, fichiers remplacés, <strong>migrations de schéma en attente appliquées</strong>). Sinon, envoyer un nouveau\n<code>.zip</code> via <em>Ajouter</em> met aussi à jour (une version supérieure remplace l\'ancienne).</li>\n<li><strong>Retirer</strong> : depuis la fiche de l\'addon dans <strong>Thèmes &amp; Addons</strong>, <strong>Supprimer</strong> (l\'addon doit être\ndésactivé). Ses tables et données sont retirées.</li>\n</ul>\n<blockquote>\n<p>Les <strong>connecteurs d\'authentification</strong> (Discord, GitHub, Google) font partie du <strong>cœur</strong> : ils sont\ndéjà présents, à configurer dans les réglages — ils ne passent pas par le marketplace.</p>\n</blockquote>\n<blockquote>\n<p><strong>Marketplace injoignable ?</strong> Si l\'écran « Mises à jour » affiche « Marketplace injoignable », vérifie\nque ton serveur peut sortir en <strong>HTTPS</strong> vers <code>neofrag-reborn.xyz</code>. Le catalogue est fixé à cette origine ;\nun administrateur peut la surcharger (vers un hôte autorisé, en HTTPS) via le réglage <code>nf_marketplace_url</code>.</p>\n</blockquote>\n<h2>Sécurité</h2>\n<p>Le marketplace ne télécharge que depuis une <strong>origine fixe</strong> en <strong>HTTPS</strong> (jamais une URL saisie par\nl\'utilisateur), vérifie le <strong>SHA-256</strong> de chaque archive contre le catalogue, et <strong>refuse toute archive\npiégée</strong> (anti-zip-slip : chemins absolus, <code>..</code>, symlinks). Aucun code distant n\'est exécuté lors de\nl\'ajout/mise à jour d\'un addon (extraction + <code>install.sql</code>/migrations SQL idempotents uniquement).</p>\n<h2>Pour les auteurs d\'addons</h2>\n<p>Le catalogue est généré depuis le dépôt par <code>tools/package-addons.php</code>, qui zippe chaque addon\n(dossier <code>&lt;name&gt;/</code> à la racine de l\'archive) et produit <code>marketplace/catalog.json</code> :</p>\n<pre><code class=\"language-json\">{\n  &quot;schema&quot;: 1, &quot;base_version&quot;: &quot;1.0.0&quot;,\n  &quot;addons&quot;: [{\n    &quot;type&quot;: &quot;module&quot;, &quot;name&quot;: &quot;wiki&quot;, &quot;tier&quot;: 2, &quot;category&quot;: &quot;contenu&quot;,\n    &quot;title&quot;: &quot;Wiki&quot;, &quot;version&quot;: &quot;1.0&quot;, &quot;file&quot;: &quot;modules/wiki.zip&quot;,\n    &quot;size&quot;: 15114, &quot;sha256&quot;: &quot;…&quot;, &quot;provides_widgets&quot;: []\n  }]\n}\n</code></pre>\n<p><code>catalog.json</code> et les <code>.zip</code> doivent être publiés <strong>ensemble</strong> (jeu cohérent du même run : les empreintes\nSHA-256 dépendent du run). Pour proposer ton addon, suis les guides\n<a href=\"create-a-module\">créer un module</a>, <a href=\"create-a-widget\">un widget</a> ou\n<a href=\"create-a-theme\">un thème</a>, puis zippe son dossier.</p>\n<h2>Héberger le catalogue (opérateur)</h2>\n<p>Le marketplace est un <strong>jeu de fichiers statiques</strong> servi sur le domaine de la marketplace : <code>catalog.json</code></p>\n<ul>\n<li>les <code>.zip</code> (rangés sous <code>modules/</code>, <code>widgets/</code>, <code>themes/</code>).</li>\n</ul>\n<ol>\n<li><code>php tools/package-addons.php</code> → (re)génère <code>marketplace/catalog.json</code> + les zips à jour.</li>\n<li>Uploade le contenu de <code>marketplace/</code> à la racine du site → <code>https://&lt;host&gt;/marketplace/catalog.json</code>.</li>\n<li>Le CMS pointe vers ce catalogue via <strong><code>nf_marketplace_url</code></strong> (défaut : <code>https://neofrag-reborn.xyz/marketplace</code>,\n<strong>sans <code>www</code></strong>). Origines autorisées (anti-SSRF, HTTPS:443) : <code>neofrag-reborn.xyz</code> et <code>www.neofrag-reborn.xyz</code> ;\npour un autre domaine, adapte <code>nf_marketplace_url</code> <strong>et</strong> <code>MARKETPLACE_HOSTS</code> dans <code>install/lib/installer.php</code>.</li>\n</ol>\n<p>À refaire <strong>à chaque changement d\'addon</strong> (version ou fichiers) : les SHA-256 du catalogue doivent\ncorrespondre aux zips publiés (même run).</p>\n<h2>Mise à jour du cœur (NeoFrag lui-même)</h2>\n<p>Le catalogue porte <code>base_version</code> (la version du CMS pour laquelle il a été bâti). <strong>Admin → Thèmes &amp; Addons\n→ Mises à jour</strong> la compare à la version installée et <strong>signale</strong> une nouvelle version du cœur le cas échéant.\nLa mise à jour reste <strong>manuelle</strong> : télécharge la release et remplace les fichiers (hors <code>config/</code>, <code>upload/</code>,\n<code>backups/</code>), puis visite le site (les migrations s\'appliquent).</p>\n<blockquote>\n<p>L\'<strong>auto-update par overlay</strong> (bouton du Monitoring) est <strong>désactivé sur ce fork</strong> (<code>NEOFRAG_ALLOW_AUTOUPDATE</code>) :\nl\'ancien mécanisme téléchargeait la release <strong>upstream</strong> (<code>neofrag.download</code>) et l\'écrasait par-dessus —\nce qui détruirait le code Reborn divergé. Le réactiver suppose une <strong>source de release propre au fork</strong>.</p>\n</blockquote>\n', '14', '4', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47'),
('23', 'framework', 'Le framework', '<h1>Le framework</h1>\n<p>Référence des briques que tu manipules en écrivant des addons. Pour l\'architecture\ninterne complète, voir <code>docs/architecture.md</code>.</p>\n<h2>Le service locator — <code>NeoFrag()</code></h2>\n<p>Tout le framework est accessible via le singleton global <code>NeoFrag()</code> et, dans une\nclasse d\'addon, via <code>$this</code> (qui y délègue). Les services s\'obtiennent par méthodes\nmagiques :</p>\n<pre><code class=\"language-php\">$this-&gt;db        // accès base de données\n$this-&gt;config    // configuration du site (nf_name, nf_default_theme…)\n$this-&gt;user      // membre courant\n$this-&gt;url       // requête / segments / base\n$this-&gt;lang(...) // traduction\n$this-&gt;module(\'forum\');         // un module\nNeoFrag()-&gt;model2(\'addon\');      // un modèle\n</code></pre>\n<h2>Routing</h2>\n<p>Un module déclare ses routes dans <code>__info().routes</code> : <code>motif =&gt; méthode</code>.</p>\n<pre><code class=\"language-php\">\'routes\' =&gt; [\n    \'\'                 =&gt; \'index\',   // page d\'accueil du module\n    \'{id}/{url_title}\' =&gt; \'_show\',    // /module/42/slug\n    \'admin{pages}\'     =&gt; \'index\',    // admin paginée\n],\n</code></pre>\n<ul>\n<li>Placeholders <strong>fixes</strong> : <code>{id}</code> (entier), <code>{key_id}</code>, <code>{url_title}</code> (slug), <code>{url_title*}</code>,\n<code>{page}</code> et <code>{pages}</code> (pagination). Un placeholder inconnu → 404 silencieux.</li>\n<li>Cycle : le <strong>checker</strong> (<code>controllers/checker.php</code>) valide la route et charge les\ndonnées ; ce qu\'il <strong>retourne</strong> devient les arguments de la méthode homonyme du\n<strong>contrôleur</strong> (<code>controllers/index.php</code>).</li>\n</ul>\n<blockquote>\n<p>En test/curl, <code>is_crawler</code> saute la session : envoie un <strong>User-Agent de navigateur</strong>.</p>\n</blockquote>\n<h2>ORM — Model2</h2>\n<p>Query builder fluide. La table porte le préfixe <code>nf_</code>.</p>\n<pre><code class=\"language-php\">$rows = NeoFrag()-&gt;db\n    -&gt;select(\'id\', \'title\', \'created\')\n    -&gt;from(\'nf_news\')\n    -&gt;where(\'published\', \'1\')\n    -&gt;where(\'author_id\', $user_id)\n    -&gt;order_by(\'created DESC\')\n    -&gt;limit(10)\n    -&gt;get();                 // tableau de lignes ; -&gt;row() pour une seule\n\n$id = NeoFrag()-&gt;db-&gt;insert(\'nf_news\', [\'title\' =&gt; $t, \'body\' =&gt; $b]);  // renvoie l\'id\nNeoFrag()-&gt;db-&gt;where(\'id\', $id)-&gt;update(\'nf_news\', [\'title\' =&gt; $t2]);\nNeoFrag()-&gt;db-&gt;where(\'id\', $id)-&gt;delete(\'nf_news\');\n</code></pre>\n<p>Pour les entités gérées (addons, fichiers…), passe par les <strong>modèles</strong> :\n<code>NeoFrag()-&gt;model2(\'addon\')</code>, <code>NeoFrag()-&gt;model2(\'file\', $id)-&gt;delete()</code>. Pour itérer un ensemble typé\n(p. ex. tous les addons installés), <code>NeoFrag()-&gt;collection(\'addon\')-&gt;get()</code>.</p>\n<h2>Formulaires — <code>form()</code> &amp; <code>form2()</code></h2>\n<p>Deux API coexistent — choisis selon le contexte :</p>\n<ul>\n<li><strong><code>form2()</code></strong> — fluide, chaque champ est un objet <code>form_*()</code>. Idéale pour les formulaires <strong>publics</strong> ou\n<strong>riches</strong>, et c\'est la <strong>seule</strong> qui valide un formulaire de <strong>confirmation seule</strong> (sans champ).</li>\n<li><strong><code>form()</code></strong> — l\'API <strong>historique</strong>, employée par les <strong>écrans d\'administration</strong> des modules : champs\ndéclarés en tableau via <code>add_rules([...])</code>, traitée par <code>is_valid($post)</code>, rendue par <code>-&gt;display()</code>.\nExemple complet dans <a href=\"create-a-module\">Créer un module</a> (§7 — l\'administration).</li>\n</ul>\n<p><code>form2()</code> construit, valide (CSRF inclus) et traite un formulaire :</p>\n<pre><code class=\"language-php\">return $this-&gt;form2()\n    -&gt;rule($this-&gt;form_text(\'title\')-&gt;title($this-&gt;lang(\'Titre\'))-&gt;required())\n    -&gt;rule($this-&gt;form_textarea(\'body\')-&gt;title($this-&gt;lang(\'Contenu\')))\n    -&gt;success(function ($data) {\n        NeoFrag()-&gt;db-&gt;insert(\'nf_news\', $data);\n        notify(\'Enregistré\');\n    })\n    -&gt;submit(\'Publier\');\n</code></pre>\n<blockquote>\n<p>Un formulaire de <strong>confirmation seule</strong> (sans champ) ne se valide pas avec <code>form()</code> :\nutilise <code>form2</code>. Le checker reçoit le <strong>vrai titre</strong>, pas le slug.</p>\n</blockquote>\n<h2>Tables — Table2</h2>\n<p><code>table2()</code> rend des listes paginées, triables et cherchables à partir d\'une requête —\nidéal pour les écrans d\'administration (ex. la liste des membres, <code>modules/user/controllers/admin.php</code>).</p>\n<h2>Traductions</h2>\n<p><code>$this-&gt;lang(\'Clé\')</code> renvoie la traduction. Les fichiers <code>langs/fr.php</code> mappent le\n<strong>crc32b de la clé source</strong> vers la traduction :</p>\n<pre><code class=\"language-php\">return [\n    hash(\'crc32b\', \'Bienvenue\') =&gt; \'Bienvenue\',   // ou directement \'467f39a3\' =&gt; \'…\'\n];\n</code></pre>\n<p><code>$this-&gt;lang(\'%d élément(s)\', $n)</code> accepte des arguments (style <code>sprintf</code>).</p>\n<h2>Helpers utiles</h2>\n<ul>\n<li><code>url(\'forum/42\')</code> — construit une URL routée (préfixe langue inclus).</li>\n<li><code>$this-&gt;config-&gt;nf_name</code>, <code>-&gt;nf_default_theme</code> — config du site.</li>\n<li><code>notify(\'Message\', \'success\')</code> — toast.</li>\n<li><code>htmlspecialchars(...)</code> / <code>sanitize_html(...)</code> — échappement / nettoyage anti-XSS\n(HTMLPurifier) pour le HTML riche entrant et sortant.</li>\n</ul>\n<h2>Migrations</h2>\n<p>Le schéma évolue par migrations versionnées, suivies dans <code>nf_migrations</code> :</p>\n<pre><code class=\"language-bash\">php tools/migrate.php status                 # appliqué / en attente\nphp tools/migrate.php up [--pretend]          # applique (dry-run avec --pretend)\nphp tools/migrate.php down [--step=N]         # annule\nphp tools/migrate.php baseline --until=NAME   # adopter une base existante\n</code></pre>\n<p>Fichiers : <code>migrations/AAAA_MM_JJ_nom.up.sql</code> (+ <code>.down.sql</code> pour la réversibilité).\nLe DDL MySQL est auto-commit → <strong>backup avant <code>up</code> en prod</strong>.</p>\n<h2>Surcharge à trois niveaux</h2>\n<p>Résolution des vues/classes/fichiers (premier trouvé gagne) :</p>\n<ol>\n<li><code>overrides/{type}/{fichier}</code> — global</li>\n<li><code>themes/{thème actif}/overrides/{type}/{fichier}</code> — par thème</li>\n<li>l\'original livré</li>\n</ol>\n<p>Tu personnalises sans forker et sans casser les mises à jour.</p>\n<h2>Environnement de dev</h2>\n<p>Stack Docker : <code>web</code> (Apache + PHP 8.3), <code>db</code> (MariaDB 11), <code>phpmyadmin</code>, <code>mailpit</code>.</p>\n<pre><code class=\"language-bash\">docker compose up -d                 # http://localhost:8080\ndocker compose exec web composer test\n</code></pre>\n<p>Voir <code>docs/development.md</code> pour le détail (CI, SCSS, déploiement).</p>\n', '19', '4', '1', NULL, '0', '2026-06-09 16:09:47', '2026-06-09 16:09:47');
